+{
+  // The runtime can be driven by the registered manifest instead of config
+  // macros: the transported set is a union of complete gate-groups, so setting
+  // each transported CSR's gate reconstructs the EXACT caps. Proven to match the
+  // config-shape helpers for both built engines -- so config -> caps (from_config)
+  // and manifest -> caps (from_transport_set) are interchangeable.
+  for (const AndesCaps want : {premium(), advanced()}) {
+    std::vector<uint16_t> transported;
+    for (int a = 0; a <= 0xFFF; ++a) {
