77	struct RecordingBus final : hybrid::DmiBus
78	{
79	  std::vector<DmiOp> ops;
80	
81	  // bit 9: allhalted, bit 17: allresumeack. Answering both lets the poll
82	  // loops finish on their first read. abstractcs reads return 0 (busy clear,
83	  // no cmderr), so each abstract write completes immediately.
84	  uint32_t dmstatus_value = 0;
85	
86	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
87	  // cmderr (cleared only by the W1C abstractcs write the driver issues).
88	  // Models a hart that NACKs a particular abstract CSR access.
89	  std::optional<uint16_t> fail_csr_write;
90	
91	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
92	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
93	  // re-arms to false after firing - tests can flip it back on to fail a
94	  // later PB exec.
95	  bool fail_next_pb_exec = false;
96	
97	  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
98	  // into regfile[regno]; abstract read-COMMANDs load it back so a read-modify-
99	  // write-verify sequence (dcsr.prv) observes its own writes. Regnos in
100	  // warl_ignore model WARL fields the hart pins (the write is recorded but
101	  // discarded), e.g. dcsr.prv on an M-only core.
102	  std::unordered_map<uint16_t, uint64_t> regfile;
103	  std::set<uint16_t> warl_ignore;
104	
105	  void write(uint8_t reg, uint32_t value) override
106	  {
107	    ops.push_back({DmiOp::Kind::Write, reg, value});
108	    if (reg == kData0) staged_data0_ = value;
109	    if (reg == kData1) staged_data1_ = value;
110	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
111	      cmderr_sticky_ = false;  // W1C clear
112	    if (reg == kCommand && fail_csr_write) {
113	      const auto regno    = static_cast<uint16_t>(value & 0xffffu);
114	      const bool is_write = ((value >> 16) & 1u) != 0u;
115	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
116	        cmderr_sticky_ = true;
117	    }
118	    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
119	      const auto regno    = static_cast<uint16_t>(value & 0xffffu);
120	      const bool is_write = ((value >> 16) & 1u) != 0u;
121	      if (is_write) {
122	        if (!warl_ignore.count(regno))
123	          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
124	      } else {
125	        const auto it = regfile.find(regno);
126	        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
127	        pending_data0_ = static_cast<uint32_t>(v);
128	        pending_data1_ = static_cast<uint32_t>(v >> 32);
129	      }
130	    }
131	    if (reg == kCommand && value == hybrid::kExecProgbufCmd
132	        && fail_next_pb_exec) {
133	      cmderr_sticky_ = true;
134	      fail_next_pb_exec = false;
135	    }
136	  }
137	
138	  auto read(uint8_t reg) -> uint32_t override
139	  {
140	    ops.push_back({DmiOp::Kind::Read, reg, 0});
141	    if (reg == kDmstatus) return dmstatus_value;
142	    if (reg == kData0) return pending_data0_;
143	    if (reg == kData1) return pending_data1_;
144	    if (reg == kAbstractcs && cmderr_sticky_) return kCmderrMask;
145	    return 0;
146	  }
147	
148	private:
149	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
150	  bool cmderr_sticky_ = false;
151	  uint32_t staged_data0_  = 0;
152	  uint32_t staged_data1_  = 0;
153	  uint32_t pending_data0_ = 0;
154	  uint32_t pending_data1_ = 0;
155	};
