// v4 M-ext completion: the whole HYBRID_M_EXT_CSR_LIST block restores via one
// caps-gated abstract write per CSR -- never a batched Program-Buffer sweep,
// which could not tolerate a cmderr on one CSR without corrupting the rest of
// the batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas
// the per-CSR abstract path clears the error and moves on.
TEST_CASE("CSR restore is Abstract-Command-only: every Andes+M-ext CSR gets "
          "its own abstract write, never a Program-Buffer batch")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
